settings.custom_liquid:
{%- liquid
  assign handles = 'philodendron-spiritus-sancti-rear,monstera-bulbasaur-pre-order,philodendron-mcdowell,monstera-white-monster-pre-order,monstera-obliqua-peru,philodendron-tortum,tissue-culture-starter-kit,monstera-creme-brulee-pre-order,monstera-placer-gold-pre-order,monstera-deliciosa-aurea-pre-order,monstera-devil-monster-premium-variegated-pre-order,monstera-deliciosa-banana-super-golden-pre-order,philodendron-billietiae-variegated-pre-order,philodendron-florida-beauty-x-tortum,alocasia-frydek-variegated-pre-order,philodendron-gloriosum-variegated-pre-order,philodendron-goeldii-mint,scindapsus-pictus-variegated' | split: ','
  assign total_reviews = 0
  assign rating_points = 0
  comment
    Review IDs to keep out of the featured cards. Does NOT affect the average --
    that still counts every review. Skipped: two photos shot through a fogged
    prop-box lid (murky, the plant is barely readable), and one whose text opens
    "came slightly bent".
  endcomment
  assign skip_ids = 'NI-wlpvmPy,qocHgh3EC,y_v4cpIr5' | split: ','
  assign max_cards = 11
  assign per_product = 2
-%}
{%- for h in handles -%}
  {%- assign p = all_products[h] -%}
  {%- assign n = p.metafields.loox.num_reviews.value -%}
  {%- if n > 0 -%}
    {%- assign total_reviews = total_reviews | plus: n -%}
    {%- assign pts = p.metafields.loox.avg_rating.value | times: n -%}
    {%- assign rating_points = rating_points | plus: pts -%}
  {%- endif -%}
{%- endfor -%}
{%- if total_reviews > 0 -%}
  {%- assign avg_all = rating_points | divided_by: total_reviews | round: 1 -%}
  {%- assign avg_stars = avg_all | round -%}

<div class="ap-reviews">
  <div class="ap-reviews__head">
    <h2>What collectors say</h2>
    <p class="ap-reviews__agg">
      <span class="ap-stars" aria-hidden="true">{% for i in (1..5) %}{% if i <= avg_stars %}&#9733;{% else %}&#9734;{% endif %}{% endfor %}</span>
      <span class="ap-reviews__agg-text">{{ avg_all }} average from {{ total_reviews }} verified reviews</span>
    </p>
  </div>

  <div class="ap-reviews__grid">
    {%- assign shown = 0 -%}
    {%- for h in handles -%}
      {%- assign p = all_products[h] -%}
      {%- assign feed = p.metafields.loox.review_feed.value -%}
      {%- if feed.reviews and shown < max_cards -%}
        {%- assign from_product = 0 -%}
        {%- for r in feed.reviews -%}
          {%- assign is_skipped = false -%}
          {%- if skip_ids contains r.id -%}{%- assign is_skipped = true -%}{%- endif -%}
          {%- if from_product < per_product and shown < max_cards and r.rating >= 5 and r.review.size > 25 and is_skipped == false -%}
            {%- assign photo = '' -%}
            {%- if r.media.size > 0 -%}{%- assign photo = r.media[0].src -%}
            {%- elsif r.img.src -%}{%- assign photo = r.img.src -%}{%- endif -%}
            {%- if photo != '' -%}
              {%- assign from_product = from_product | plus: 1 -%}
              {%- assign shown = shown | plus: 1 -%}
              <figure class="ap-review">
                <img class="ap-review__photo" src="{{ photo }}" alt="Customer photo of {{ p.title | escape }}" loading="lazy" width="600" height="600">
                <figcaption class="ap-review__body">
                  <span class="ap-stars ap-stars--sm" aria-label="{{ r.rating }} out of 5">{% for i in (1..5) %}{% if i <= r.rating %}&#9733;{% else %}&#9734;{% endif %}{% endfor %}</span>
                  <blockquote class="ap-review__text">{{ r.review | strip | truncate: 190 }}</blockquote>
                  <span class="ap-review__who">{{ r.author }}{% if r.verified %} &middot; Verified buyer{% endif %}</span>
                  <a class="ap-review__product" href="{{ p.url }}">{{ p.title }}</a>
                </figcaption>
              </figure>
            {%- endif -%}
          {%- endif -%}
        {%- endfor -%}
      {%- endif -%}
    {%- endfor -%}
  </div>
</div>

<style>
  .ap-reviews { width: 100%; }
  .ap-reviews__head { margin-block-end: 28px; }
  .ap-reviews__head h2 {
    font-family: var(--font-heading--family);
    font-size: var(--font-size--h3);
    color: var(--color-foreground);
    margin: 0 0 8px;
  }
  .ap-reviews__agg { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin: 0; }
  .ap-stars { color: #5C6B4C; letter-spacing: 2px; font-size: 1rem; line-height: 1; }
  .ap-stars--sm { font-size: 0.8125rem; }
  .ap-reviews__agg-text {
    font-family: var(--font-body--family);
    font-size: 0.9375rem;
    color: var(--color-foreground);
  }
  .ap-reviews__grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
  }
  .ap-review {
    margin: 0;
    background: #FBF8F2;
    border: 1px solid #DED3C2;
    border-radius: 4px;
    overflow: hidden;
    display: flex;
    flex-direction: column;
  }
  .ap-review__photo {
    width: 100%;
    aspect-ratio: 1 / 1;
    object-fit: cover;
    display: block;
  }
  .ap-review__body {
    padding: 16px;
    display: flex;
    flex-direction: column;
    gap: 8px;
    flex: 1;
  }
  .ap-review__text {
    margin: 0;
    font-family: var(--font-body--family);
    font-size: 0.9375rem;
    line-height: 1.5;
    color: var(--color-foreground);
  }
  .ap-review__who {
    font-family: var(--font-subheading--family);
    font-size: 0.6875rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #56503F;
  }
  .ap-review__product {
    margin-block-start: auto;
    font-family: var(--font-body--family);
    font-size: 0.8125rem;
    color: #56503F;
    text-decoration: underline;
    text-underline-offset: 3px;
  }
  @media screen and (max-width: 989px) {
    .ap-reviews__grid { grid-template-columns: repeat(2, 1fr); }
  }
  @media screen and (max-width: 749px) {
    .ap-reviews__grid {
      grid-auto-flow: column;
      grid-auto-columns: 74%;
      grid-template-columns: none;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      margin-inline: -20px;
      padding-inline: 20px;
      scrollbar-width: none;
    }
    .ap-reviews__grid::-webkit-scrollbar { display: none; }
    .ap-review { scroll-snap-align: start; }
  }
</style>
{%- endif -%}
